public class ClasificadorNumeros {
    public static void main(String[] args) {
        int numero = -7;

        if (numero > 0) {
            System.out.println("El número " + numero + " es positivo");
        } else if (numero < 0) {
            System.out.println("El número " + numero + " es negativo");
        } else {
            System.out.println("El número es cero");
        }
    }
}

