solution:
public class CalculadoraIMC {
    public static void main(String[] args) {
        double peso = 72.0;
        double altura = 1.75;

        double imc = peso / (altura * altura);
        String categoria;

        if (imc < 18.5) {
            categoria = "Bajo peso";
        } else if (imc < 25) {
            categoria = "Normal";
        } else if (imc < 30) {
            categoria = "Sobrepeso";
        } else {
            categoria = "Obesidad";
        }

        System.out.printf("Peso: %.1f kg, Altura: %.2f m%n", peso, altura);
        System.out.printf("IMC: %.1f - %s%n", imc, categoria);
    }
}

